 public static GridDescriptor Find(string key)=>All.SingleOrDefault(x=>x.Key==key)??throw new KeyNotFoundException("Unknown data table.");
 public static IQueryable<GridRecord> Query(AppDbContext db, string key,(int company,int branch,string user)t)=>key switch
 {
  "products"=>db.StockItems.AsNoTracking().Where(x=>x.CompanyId==t.company&&x.BranchId==t.branch).Select(x=>new GridRecord{Id=x.Id,Reference=x.SKU,Description=x.Name,Status=x.UnitOfMeasure,Value=x.QuantityOnHand,Unit=x.UnitOfMeasure}),
  "animals"=>db.Animals.AsNoTracking().Where(x=>x.CompanyId==t.company&&x.BranchId==t.branch).Select(x=>new GridRecord{Id=x.Id,Reference=x.Tag,Description=x.Breed,Status=x.Sold?"Sold":"Active",Value=x.CurrentWeightKg,Unit="KG"}),
  "stock-movements"=>db.StockMovements.AsNoTracking().Where(x=>x.CompanyId==t.company&&x.BranchId==t.branch).Select(x=>new GridRecord{Id=x.Id,Reference=x.Reference,Description="Stock item " + x.StockItemId,Status=x.QuantityDelta<0?"Out":"In",Instant=x.CreatedUtc,Value=x.QuantityDelta}),
  "milk"=>db.MilkYields.AsNoTracking().Where(x=>x.CompanyId==t.company&&x.BranchId==t.branch).Select(x=>new GridRecord{Id=x.Id,Reference="Milk " + x.Id,Description="Animal " + x.AnimalId,Status=x.Session,Day=x.Date,Value=x.Litres,Unit="L"}),
  "health"=>db.AnimalHealthRecords.AsNoTracking().Where(x=>x.CompanyId==t.company&&x.BranchId==t.branch).Select(x=>new GridRecord{Id=x.Id,Reference=x.Reference,Description="Animal " + x.AnimalId,Status=x.EventType,Day=x.EventDate}),
  "feed"=>db.AnimalFeedRecords.AsNoTracking().Where(x=>x.CompanyId==t.company&&x.BranchId==t.branch).Select(x=>new GridRecord{Id=x.Id,Reference=x.Reference,Description="Animal " + x.AnimalId,Status="Recorded",Day=x.FeedDate,Value=x.Quantity}),
  "purchase-orders"=>db.PurchaseOrders.AsNoTracking().Where(x=>x.CompanyId==t.company&&x.BranchId==t.branch).Select(x=>new GridRecord{Id=x.Id,Reference=x.Reference,Description="Stock item " + x.StockItemId,Status=x.Status,Instant=x.CreatedUtc,Value=x.Quantity}),
  "receipts"=>db.PurchaseReceipts.AsNoTracking().Where(x=>x.CompanyId==t.company&&x.BranchId==t.branch).Select(x=>new GridRecord{Id=x.Id,Reference=x.Reference,Description="Stock item " + x.StockItemId,Status="Posted",Instant=x.CreatedUtc,Value=x.Quantity}),
  "sales"=>db.ProductSales.AsNoTracking().Where(x=>x.CompanyId==t.company&&x.BranchId==t.branch).Select(x=>new GridRecord{Id=x.Id,Reference=x.Reference,Description="Stock item " + x.StockItemId,Status="Posted",Instant=x.CreatedUtc,Value=x.Quantity}),
  "documents"=>db.FinanceDocuments.AsNoTracking().Where(x=>x.CompanyId==t.company&&x.BranchId==t.branch).Select(x=>new GridRecord{Id=x.Id,Reference=x.Reference,Description=x.Kind,Status="Posted",Instant=x.CreatedUtc}),
  "returns"=>db.StockDocumentReturns.AsNoTracking().Where(x=>x.CompanyId==t.company&&x.BranchId==t.branch).Select(x=>new GridRecord{Id=x.Id,Reference=x.Reference,Description="Document " + x.FinanceDocumentId,Status="Posted",Instant=x.CreatedUtc,Value=x.Quantity}),
  "parties"=>db.TradingParties.AsNoTracking().Where(x=>x.CompanyId==t.company&&x.BranchId==t.branch).Select(x=>new GridRecord{Id=x.Id,Reference=x.Code,Description=x.Name,Status=x.Active?x.Kind:"Inactive"}),
  "payments"=>db.FinancePayments.AsNoTracking().Where(x=>x.CompanyId==t.company&&x.BranchId==t.branch).Select(x=>new GridRecord{Id=x.Id,Reference=x.Reference,Description=x.PartyType,Status="Recorded",Instant=x.CreatedUtc}),
  "bank-lines"=>db.BankStatementLines.AsNoTracking().Where(x=>x.CompanyId==t.company&&x.BranchId==t.branch).Select(x=>new GridRecord{Id=x.Id,Reference=x.ExternalReference,Description="Statement line",Status=x.MatchedVoucherId.HasValue?"Matched":"Unmatched",Day=x.ValueDate}),
  "vouchers"=>db.Vouchers.AsNoTracking().Where(x=>x.CompanyId==t.company&&x.BranchId==t.branch).Select(x=>new GridRecord{Id=x.Id,Reference=x.Reference,Description="Voucher",Status=x.Posted?"Posted":"Draft",Instant=x.Date}),
  "expenses"=>db.FarmExpenses.AsNoTracking().Where(x=>x.CompanyId==t.company&&x.BranchId==t.branch).Select(x=>new GridRecord{Id=x.Id,Reference=x.Reference,Description=x.Description,Status=x.Category,Day=x.ExpenseDate}),
  "weights"=>db.AnimalWeightRecords.AsNoTracking().Where(x=>x.CompanyId==t.company&&x.BranchId==t.branch).Select(x=>new GridRecord{Id=x.Id,Reference=x.Reference,Description="Animal " + x.AnimalId,Status="Recorded",Day=x.WeighedOn,Value=x.WeightKg,Unit="KG"}),
  "fattening"=>db.FatteningPlans.AsNoTracking().Where(x=>x.CompanyId==t.company&&x.BranchId==t.branch).Select(x=>new GridRecord{Id=x.Id,Reference=x.Reference,Description="Animal " + x.AnimalId,Status="Planned",Day=x.StartDate,Value=x.TargetWeightKg,Unit="KG"}),
  "breeding"=>db.BreedingCycles.AsNoTracking().Where(x=>x.CompanyId==t.company&&x.BranchId==t.branch).Select(x=>new GridRecord{Id=x.Id,Reference=x.Reference,Description="Animal " + x.AnimalId,Status=x.Status,Day=x.ServiceDate}),
  "staff"=>db.HRPayrollStaff.AsNoTracking().Where(x=>x.CompanyId==t.company&&x.BranchId==t.branch).Select(x=>new GridRecord{Id=x.Id,Reference=x.Code,Description=x.Name,Status=x.Active?"Active":"Inactive",Day=x.StartDate}),
  "attendance"=>db.HRPayrollAttendance.AsNoTracking().Where(x=>x.CompanyId==t.company&&x.BranchId==t.branch).Select(x=>new GridRecord{Id=x.Id,Reference="Attendance " + x.Id,Description="Staff " + x.StaffId,Status="Recorded",Day=x.Date,Value=x.PaidDays,Unit="days"}),
  "leave"=>db.HRPayrollLeaves.AsNoTracking().Where(x=>x.CompanyId==t.company&&x.BranchId==t.branch).Select(x=>new GridRecord{Id=x.Id,Reference="Leave " + x.Id,Description="Staff " + x.StaffId,Status=x.Status,Day=x.From}),
  "payroll-policies"=>db.HRPayrollPolicies.AsNoTracking().Where(x=>x.CompanyId==t.company&&x.BranchId==t.branch).Select(x=>new GridRecord{Id=x.Id,Reference="Policy " + x.Id,Description=x.Name,Status=x.Reviewed?"Reviewed":"Pending",Day=x.EffectiveFrom}),
  "payroll-runs"=>db.HRPayrollRuns.AsNoTracking().Where(x=>x.CompanyId==t.company&&x.BranchId==t.branch).Select(x=>new GridRecord{Id=x.Id,Reference=x.Reference,Description=x.Currency,Status=x.Status,Day=x.PeriodStart}),
  "crm-leads"=>db.CRMLeads.AsNoTracking().Where(x=>x.CompanyId==t.company&&x.BranchId==t.branch).Select(x=>new GridRecord{Id=x.Id,Reference=x.Reference,Description=x.Name,Status=x.Status,Instant=x.CreatedUtc}),
  "crm-opportunities"=>db.CRMOpportunities.AsNoTracking().Where(x=>x.CompanyId==t.company&&x.BranchId==t.branch).Select(x=>new GridRecord{Id=x.Id,Reference=x.Reference,Description=x.Title,Status=x.Stage,Day=x.ExpectedCloseDate}),
  "crm-activities"=>db.CRMActivities.AsNoTracking().Where(x=>x.CompanyId==t.company&&x.BranchId==t.branch).Select(x=>new GridRecord{Id=x.Id,Reference=x.Reference,Description=x.Title,Status=x.Status,Day=x.DueDate}),
  "crm-quotes"=>db.CRMQuotes.AsNoTracking().Where(x=>x.CompanyId==t.company&&x.BranchId==t.branch).Select(x=>new GridRecord{Id=x.Id,Reference=x.Reference,Description=x.CustomerName,Status=x.Status,Day=x.QuoteDate}),
  "crm-ready"=>db.CRMSalesReadyRecords.AsNoTracking().Where(x=>x.CompanyId==t.company&&x.BranchId==t.branch).Select(x=>new GridRecord{Id=x.Id,Reference=x.Reference,Description=x.CustomerName,Status="Internal handoff",Instant=x.CreatedUtc}),
  "assets"=>db.FixedAssets.AsNoTracking().Where(x=>x.CompanyId==t.company&&x.BranchId==t.branch).Select(x=>new GridRecord{Id=x.Id,Reference=x.AssetCode,Description=x.Name,Status=x.Status,Day=x.AcquisitionDate}),
  "depreciation"=>db.FixedAssetDepreciationRuns.AsNoTracking().Where(x=>x.CompanyId==t.company&&x.BranchId==t.branch).Select(x=>new GridRecord{Id=x.Id,Reference=x.Reference,Description=x.CurrencyCode,Status=x.Status,Day=x.Period}),
  "disposals"=>db.FixedAssetDisposals.AsNoTracking().Where(x=>x.CompanyId==t.company&&x.BranchId==t.branch).Select(x=>new GridRecord{Id=x.Id,Reference=x.Reference,Description=x.Counterparty,Status=x.Status,Day=x.DisposalDate}),
  "ecommerce-catalog"=>db.EcommerceProducts.AsNoTracking().Where(x=>x.CompanyId==t.company&&x.BranchId==t.branch).Select(x=>new GridRecord{Id=x.Id,Reference="Product " + x.Id,Description=x.Title,Status=x.Published?"Published":"Unpublished"}),
  "ecommerce-orders"=>db.EcommerceOrders.AsNoTracking().Where(x=>x.CompanyId==t.company&&x.BranchId==t.branch).Select(x=>new GridRecord{Id=x.Id,Reference=x.Reference,Description=x.CustomerName,Status=x.Status,Instant=x.CreatedUtc}),
  "own-orders"=>db.EcommerceOrders.AsNoTracking().Where(x=>x.CompanyId==t.company&&x.BranchId==t.branch&&db.EcommerceCustomers.Any(c=>c.Id==x.EcommerceCustomerId&&c.CompanyId==t.company&&c.BranchId==t.branch&&c.UserId==t.user&&c.Active)).Select(x=>new GridRecord{Id=x.Id,Reference=x.Reference,Description=x.DeliveryMethod,Status=x.Status,Instant=x.CreatedUtc}),
  "support"=>db.SupportTickets.AsNoTracking().Where(x=>x.CompanyId==t.company&&x.BranchId==t.branch).Select(x=>new GridRecord{Id=x.Id,Reference=x.TicketNumber,Description=x.Subject,Status=x.Status,Instant=x.CreatedUtc}),
  "automation-notifications"=>db.Notifications.AsNoTracking().Where(x=>x.CompanyId==t.company&&x.BranchId==t.branch).Select(x=>new GridRecord{Id=x.Id,Reference=x.ExecutionKey,Description=x.Message,Status=x.Category,Instant=x.CreatedUtc}),
  "automation-rules"=>db.AutomationRules.AsNoTracking().Where(x=>x.CompanyId==t.company).Select(x=>new GridRecord{Id=x.Id,Reference="Rule " + x.Id,Description=x.Name,Status=x.Active?"Active":"Inactive"}),
  "automation-jobs"=>db.ScheduledJobs.AsNoTracking().Where(x=>x.CompanyId==t.company).Select(x=>new GridRecord{Id=x.Id,Reference=x.ExecutionKey,Description="Rule " + x.RuleId,Status=x.Status,Instant=x.DueUtc}),
  "automation-approvals"=>db.AutomationApprovals.AsNoTracking().Where(x=>x.CompanyId==t.company).Select(x=>new GridRecord{Id=x.Id,Reference="Approval " + x.Id,Description="Rule " + x.RuleId,Status=x.Status,Instant=x.CreatedUtc}),
  "subscription-invoices"=>db.SubscriptionInvoices.AsNoTracking().Where(x=>x.CompanyId==t.company).Select(x=>new GridRecord{Id=x.Id,Reference=x.Reference,Description="Subscription",Status=x.Cancelled?"Cancelled":x.Paid>=x.Amount?"Paid":"Open",Day=x.DueDate}),
  "subscription-payments"=>db.SubscriptionPayments.AsNoTracking().Where(x=>x.CompanyId==t.company).Select(x=>new GridRecord{Id=x.Id,Reference=x.Reference,Description="Invoice " + x.InvoiceId,Status="Recorded",Instant=x.RecordedUtc}),
  "company-policies"=>db.CompanyBusinessPolicies.AsNoTracking().Where(x=>x.CompanyId==t.company).Select(x=>new GridRecord{Id=x.Id,Reference="Version " + x.Version,Description=x.CountryCode + " / " + x.CurrencyCode,Status=x.Status,Day=x.EffectiveFrom}),
  "tax-policies"=>db.TaxPolicies.AsNoTracking().Where(x=>x.CompanyId==t.company).Select(x=>new GridRecord{Id=x.Id,Reference=x.Code,Description=x.Name,Status=x.Status,Day=x.EffectiveFrom}),
  "opening-balances"=>db.OpeningBalances.AsNoTracking().Where(x=>x.CompanyId==t.company&&x.BranchId==t.branch).Select(x=>new GridRecord{Id=x.Id,Reference=x.Reference,Description="Opening balance",Status="Posted",Day=x.OpeningDate}),
  "stock-transfers"=>db.StockTransfers.AsNoTracking().Where(x=>x.CompanyId==t.company&&(x.SourceBranchId==t.branch||x.DestinationBranchId==t.branch)&&db.UserBranchAccess.Any(a=>a.CompanyId==t.company&&a.UserId==t.user&&a.BranchId==x.SourceBranchId)&&db.UserBranchAccess.Any(a=>a.CompanyId==t.company&&a.UserId==t.user&&a.BranchId==x.DestinationBranchId)).Select(x=>new GridRecord{Id=x.Id,Reference=x.Reference,Description=x.SourceSku+" → "+x.DestinationSku,Status="Posted",Instant=x.CreatedUtc,Value=x.Quantity,Unit=x.UnitOfMeasure}),
  "own-payslips"=>db.HRPayrollLines.AsNoTracking().Where(x=>x.CompanyId==t.company&&x.BranchId==t.branch&&db.HRPayrollStaff.Any(s=>s.Id==x.StaffId&&s.CompanyId==t.company&&s.BranchId==t.branch&&s.IdentityUserId==t.user)&&db.HRPayrollRuns.Any(r=>r.Id==x.RunId&&r.CompanyId==t.company&&r.BranchId==t.branch&&r.Status=="Posted")).Select(x=>new GridRecord{Id=x.Id,Reference=x.StaffCode,Description=x.StaffName,Status="Posted",RelatedId=x.RunId,Day=db.HRPayrollRuns.Where(r=>r.Id==x.RunId&&r.CompanyId==t.company&&r.BranchId==t.branch).Select(r=>(DateOnly?)r.PeriodEnd).FirstOrDefault()}),
  _=>throw new KeyNotFoundException("Unknown data table.")
 };
}
